import numpy as np

def problem(x: np.ndarray) -> float:
    """
    Synthetic benchmark function combining quadratic, linear, and interaction components with a scaled sigmoid and a weight on the first variable.

    Formula:
    f(x) = 0.1 * sigmoid(sum_i (x_i^2) + 0.4 * sum_i (x_i) + 0.005 * sum_{i<j} (x_i * x_j) + 0.2 * sigmoid(x[0]) + 0.03 * x[0]**3)

    where sigmoid(x) = 1 / (1 + exp(-x))
    """
    n = len(x)
    quadratic_term = np.sum(x**2)
    linear_term = 0.4 * np.sum(x)
    interaction_term = 0
    for i in range(n):
        for j in range(i + 1, n):
            interaction_term += x[i] * x[j]

    def sigmoid(z):
        return 1 / (1 + np.exp(-z))

    sigmoid_term = 0.2 * sigmoid(x[0])
    cubic_term = 0.03* x[0]**3

    return 0.1 * sigmoid(quadratic_term + linear_term + 0.005 * interaction_term + sigmoid_term + cubic_term)
